-- Generated from public/catalogue.json by scripts/generate-supabase-seed.mjs.
-- Demo prices and the initial category assignment require business review before production.
on conflict (id) do update set
  category_id = excluded.category_id,
  marque = excluded.marque,
  gamme = excluded.gamme,
  sous_reference = excluded.sous_reference,
  viscosite = excluded.viscosite,
  litrage = excluded.litrage,
  designation = excluded.designation,
  price = excluded.price,
  recto = excluded.recto,
  verso = excluded.verso,
  statut_recto = excluded.statut_recto,
  statut_verso = excluded.statut_verso,
  references_articles = excluded.references_articles,
  reference_image = excluded.reference_image,
  origine_image = excluded.origine_image,
  preuves_maroc = excluded.preuves_maroc,
  source_recto = excluded.source_recto,
  source_verso = excluded.source_verso,
  url_recto = excluded.url_recto,
  url_verso = excluded.url_verso,
  photo_revendeur_url = excluded.photo_revendeur_url,
  note = excluded.note,
  is_published = excluded.is_published,
  show_on_website = excluded.show_on_website
  , updated_at = now();
